SELECT * FROM crm_opportunity_stage_history WHERE tenant_id = #{tenantId} AND opportunity_id = #{id}
    AND JSON_UNQUOTE(JSON_EXTRACT(snapshot, '$.direction')) = 'REOPEN'
ORDER BY history_id DESC LIMIT 1

SELECT contract_id, tenant_id, customer_id, currency, status, version, deleted, signed_flag, start_date
FROM oa_contract contract WHERE contract.tenant_id = #{tenantId}
    AND ((contract.source_type = 'CRM_OPPORTUNITY' AND contract.source_id = #{id})
        OR EXISTS(SELECT 1 FROM crm_quote quote WHERE quote.tenant_id = contract.tenant_id AND quote.opportunity_id = #{id}
            AND ((contract.source_type = 'CRM_QUOTE' AND contract.source_id = quote.quote_id) OR quote.contract_id = contract.contract_id)))
ORDER BY contract_id
